import corpus from "../../🧫️fixtures/🪶️sqlite/🔣️.json";
const ddl=readFileSync(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url),"utf8");
test("Energy handcrafted SQL has exact relational IEEE and structural foreign-key domains",()=>{
 const db=new Database(":memory:");try{db.exec("PRAGMA foreign_keys=ON");db.exec(ddl);
 const tables=db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all() as {name:string}[];
 expect(tables.length).toBe(69);
 for(const {name} of tables){const columns=db.query(`PRAGMA table_info(${name})`).all() as {name:string,type:string}[];const names=columns.map(column=>column.name);for(const column of columns.filter(column=>column.type==="REAL")){expect(names).toContain(`${column.name}_ieee754_bits`);expect(names).toContain(`${column.name}_ieee754_class`);}expect(names.some(name=>name==="json"||name==="payload")).toBe(false);}
 expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);
 }finally{db.close();}
});
test("Energy independent SQLite retains duplicate unresolved domain IDs and raw numeric words",()=>{
 const db=new Database(":memory:",{safeIntegers:true});try{db.exec("PRAGMA foreign_keys=ON");db.exec(ddl);
 db.query("INSERT INTO energy_document VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(1,corpus.schema,"oracle","1",0,0,0,0,0,0,0,0,255,255,65535,0n,"finite",0n,"finite",0n,"finite",0n,"finite",0n,"finite",0n,"finite");
 for(let ordinal=0;ordinal<corpus.entityIds.length;ordinal++){db.query("INSERT INTO energy_constant_schedule VALUES (?,?,?,?,?,?,?)").run(ordinal+1,1,ordinal,corpus.entityIds[ordinal]!,null,BigInt.asIntN(64,BigInt(`0x${corpus.binary64Words[4]}`)),"nan");}
 const statement=db.query("SELECT schedule_id,value,value_ieee754_bits,value_ieee754_class FROM energy_constant_schedule ORDER BY ordinal");const rows=statement.all() as {schedule_id:bigint,value:null,value_ieee754_bits:bigint,value_ieee754_class:string}[];
 expect(rows.map(row=>row.schedule_id)).toEqual(corpus.entityIds.map(BigInt));expect(rows.every(row=>row.value===null&&row.value_ieee754_class==="nan"&&row.value_ieee754_bits===0x7ff8000000000042n)).toBe(true);expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);
 }finally{db.close();}
});

